	exercise_kcal_30min NVARCHAR(max) NULL, 
	converted_from NVARCHAR(max) NULL, 
	warnings NVARCHAR(max) NULL, 
	created_at DATETIME2(3) NOT NULL, 
	deleted BIT NOT NULL DEFAULT 0, 
	deleted_at DATETIME2(3) NULL, 
	deleted_by VARCHAR(64) NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES inbody.app_user (id), 
	FOREIGN KEY(upload_id) REFERENCES inbody.upload (id)
);
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'UQ_measurement_user_day_live'
               AND object_id = OBJECT_ID('inbody.measurement'))
    CREATE UNIQUE INDEX [UQ_measurement_user_day_live] ON inbody.measurement (user_id, measured_date) WHERE deleted = 0;
GO
